SID='schwartz2003';PRE='schwartz-2003-'
SRC=source(SID,'10.1021/ja036811v','Magnetic Quantum Dots: Synthesis, Spectroscopy, and Magnetism of Co2+- and Ni2+-Doped ZnO Nanocrystals','Dana A. Schwartz; Nick S. Norberg; Quyen P. Nguyen; Jason M. Parker; Daniel R. Gamelin',2003,si='Four supplied SI pages, Figures S1–S6, matched by exact main-paper declarations and cross-references plus Gamelin metadata. No standalone SI title/byline. All pages text-read and visually inspected.')
SRC['main_status']='All 14 main pages read as text and original images, including Figures 1–11, Tables 1–2, Scheme 1, equations 1–10 and references 1–51. Independent audit pending.'
def E(p,s):return ev(SID,f'Main PDF p. {p}, printed p. {13204+p}, {s}')
def SI(p,s):return ev(SID,f'Matched SI PDF p. {p}, '+s)
SYN=E(2,'II.A Sample Preparation');PHY=E(3,'II.B Physical Measurements');TOPO=SYN+E(9,'IV.C Postsynthetic Processing');KIN=E(3,'Figure 1 and kinetics discussion');MAG=E(6,'Figure 10 discussion')+E(7,'Figure 10')+E(13,'IV.D.v Ferromagnetism');OPT=E(5,'Figures 6–7 discussion')+E(6,'Figures 7–9')
def Q(v=None,u='',e=SYN,**kw):return qty(v,u,deepcopy(e),**kw)
def F(v=None,e=SYN,**kw):return fact(v,deepcopy(e),**kw)
CHEM={
 'zinc-acetate-dihydrate':('Zinc acetate dihydrate','Zn(C2H3O2)2·2H2O',SYN),
 'cobalt-acetate-tetrahydrate':('Cobalt(II) acetate tetrahydrate','Co(C2H3O2)2·4H2O',SYN),
 'nickel-perchlorate-hexahydrate':('Nickel(II) perchlorate hexahydrate','Ni(ClO4)2·6H2O',SYN),
 'tetramethylammonium-hydroxide-pentahydrate':('Tetramethylammonium hydroxide pentahydrate','C4H13NO·5H2O',SYN),
 'dmso':('Dimethyl sulfoxide','C2H6OS',SYN),'ethanol':('Ethanol','C2H6O',SYN),
 'ethyl-acetate':('Ethyl acetate','C4H8O2',SYN),'heptane':('Heptane','C7H16',SYN),
 'dodecylamine':('Dodecylamine','C12H27N',SYN),'toluene':('Toluene','C7H8',SYN),
 'topo-technical':('Technical-grade trioctylphosphine oxide (Aldrich), with unspecified phosphonic-acid impurities',None,SYN+E(2,'Note 16')),
 'topo-component':('Trioctylphosphine oxide, named component of the technical reagent','C24H51OP',SYN+E(2,'Note 16')),
 'zinc-acetate-additive':('Zinc acetate clarity-restoration additive; hydration unspecified','Zn(C2H3O2)2',SYN),
 'zno-specimen':('ZnO nanocrystal specimen; batch specified by context','ZnO',SYN),
 'co-specimen':('Co2+-doped ZnO nanocrystals; dopant content specified by specimen','ZnO:Co',SYN),
 'ni-specimen':('Ni2+-doped ZnO nanocrystals; dopant content specified by specimen','ZnO:Ni',SYN),
 'surface-co-specimen':('ZnO nanocrystals with Co intentionally bound at the surface; loading/preparation incomplete',None,SI(2,'Figure S2')),
 'co-aggregate-specimen':('Aggregated 3.6% Co2+:ZnO nanocrystals','ZnO:Co',MAG),
 'quartz':('Quartz disk for spin-coated optical film','SiO2',PHY),
 'helium':('Helium vapor for cryostat cooling','He',PHY)
}
def C(i,role,stage='synthesis',notes=None,e=None,quantities=None):
 n,f,d=CHEM[i];return material(i,n,f,role,stage,deepcopy(e or d),quantities=quantities,notes=notes or [])
def base(k,title,kind='observation',method='Source-scoped characterization and interpretation',formula='ZnO'):
 r=record(PRE+k,'Schwartz et al. (2003) · '+title,formula,'ZnO and separately Co2+- or Ni2+-doped ZnO quantum dots',method,deepcopy(SRC),'Complete 14-page main and matched four-page SI',kind)
 r['schema_version']='1.3.0';r['collection']='reviewed_literature';r['material'].update(elements=['Zn','O']+(['Co']if formula=='ZnO:Co'else['Ni']if formula=='ZnO:Ni'else[]),components=[formula],architecture='single_material')
 r['lineage'].update(source_group=SID,recipe_family='schwartz2003-zno-doping')
 r['intended_target']['composition']=F(formula,E(1,'Abstract'),note='Dopant notation denotes the material family, not a refined site occupancy. Shared analytical records retain distinct compositions in their product/sample contexts.')
 r['quality'].update(review_status='imported_unreviewed',review_scope='All supplied main and SI pages text-read and visually inspected; no cited external full texts downloaded. Independent audits and publication pending.',missing_fields=['Per-specimen synthesis batches and complete links between nominal feed doping and measured incorporation are not given.','Several workup volumes, separation hardware, stirring speed, aging times, TOPO/powder ratio and exact purification cycles are unreported.','No measured atomic coordinate file, sample-specific refined dopant occupancy, raw spectral array or full statistical error model is supplied.'],conflicts=[],requested_tasks=['precursor_selection','partial_protocol']if kind=='literature_protocol'else[],experimental_outcome='reported_product'if kind=='literature_protocol'else'not_established')
 r['context_links']=[{'label':'Complete source review','url':'../paper-review.html?id='+SID,'relation':'Main figures, matched SI, tables, equations and evidence limitations.'}]
 return r
def add(r,i,action,label,inputs,out,e,pars=None,stage='synthesis',desc='',env=None,end=None,kind='reaction_batch',depends=None,retain=False,parents=None):
 if out:r['material_states'].append(state(out,label+' output',inputs if parents is None else parents,kind))
 r['operations'].append(operation(i,action,label,deepcopy(e),inputs,[out]if out else[],depends=depends if depends is not None else([r['operations'][-1]['id']]if r['operations']else[]),parameters=pars or{},stage=stage,description=desc,environment=F(env,e),endpoint=F(end,e),retained_fraction=out if retain else None))
def P(r,i,label,e,formula=None,st=None,explicit=False,notes=None):
 p=product(i,formula or r['material']['formula'],deepcopy(e),link='explicit'if explicit else'general_context',state=st,notes=notes or[]);p['source_sample_label']=label;r['products'].append(p);return p
def M(r,i,s,prop,v,u,e,tech='Source-reported observation',conditions='',**kw):r['measurements'].append(measurement(i,s,prop,Q(v,u,e,**kw),tech,deepcopy(e),conditions))
def T(r,i,s,prop,v,e,tech='Source-reported observation',conditions='',**kw):r['measurements'].append(measurement(i,s,prop,F(v,e,**kw),tech,deepcopy(e),conditions))
def link(r,k,title,rel='Source-scoped related preparation or characterization.'):r['context_links'].append({'label':title,'url':'../records/'+PRE+k+'.html','relation':rel})
def stock(r,i,name,components,concentrations,e,prep=None,scope=''):
 r['stocks'].append({'id':i,'name':name,'components':[{'material_id':c,'quantities':{}}for c in components],'concentrations':concentrations,'preparation_operation_ids':prep or[],'scope':scope,'evidence':deepcopy(e)})
