 r=base(metal+'-route',('Undoped'if metal=='zno'else'Co2+-doped'if metal=='co'else'Ni2+-doped')+' ZnO by alkaline hydrolysis in DMSO','literature_protocol','Room-temperature alkaline hydrolysis and condensation',formula)
 inh={}if metal=='zno'else{'status':'inherited','qualifier':'Common typical preparation framework; not an independently quantified batch for each dopant concentration.'}
 r['materials']=[C('zinc-acetate-dihydrate','metal_precursor'),C('tetramethylammonium-hydroxide-pentahydrate','base'),C('dmso','solvent'),C('ethanol','solvent'),C('ethyl-acetate','antisolvent','workup'),C('heptane','alternative_antisolvent','workup')]
 if dopant:r['materials'].append(C(dopant,'metal_precursor',quantities={'initial_dopant_fraction':Q(u='mol %',qualifier='Variable nominal feed loading; not equal to the measured incorporated concentration in every characterized specimen.')}))
 comps=['zinc-acetate-dihydrate']+([dopant]if dopant else[])+['dmso']
 stock(r,'metal-stock','Zinc'+(' and dopant'if dopant else'')+' precursor in DMSO',comps,{'total_metal_concentration':Q(.101,'mol/L',**inh)},SYN,prep=['prepare-metal'],scope='For doped solutions Zn is reduced to maintain the total initial metal concentration. Individual dopant salt doses are not reported; no fixed Zn concentration is asserted for doped mixtures.')
 stock(r,'base-stock','Tetramethylammonium hydroxide in ethanol',['tetramethylammonium-hydroxide-pentahydrate','ethanol'],{'base_concentration':Q(.552,'mol/L',**inh)},SYN,prep=['prepare-base'])
 add(r,'prepare-metal','precursor_solution_preparation','Prepare the metal-acetate/DMSO solution'if metal!='ni'else'Prepare Zn acetate and Ni perchlorate in DMSO',comps,'metal-solution',SYN,{'solution_volume':Q(90,'mL',**inh),'total_metal_concentration':Q(.101,'mol/L',**inh)},stage='precursor_preparation',desc='Hydrated salts are printed explicitly. Dissolution temperature/time and water balance are unknown. '+('Replace part of Zn with the dopant to keep total metal constant; do not copy 0.101 M as the Zn-only concentration.'if dopant else'The quoted Zn stock is the typical undoped preparation.'))
 add(r,'prepare-base','base_solution_preparation','Prepare the ethanolic hydroxide feed',['tetramethylammonium-hydroxide-pentahydrate','ethanol'],'base-solution',SYN,{'solution_volume':Q(30,'mL',**inh),'base_concentration':Q(.552,'mol/L',**inh)},stage='precursor_preparation',depends=[])
 add(r,'add-base','dropwise_hydrolysis_condensation','Add the hydroxide solution dropwise with constant stirring',['metal-solution','base-solution'],'as-grown',SYN,{'addition_rate':Q(2,'mL/min',approximate=True,**inh),'base_equivalents':Q(1.8,'equiv',**inh),'temperature':Q(u='°C',qualifier='Room temperature; numerical value unreported.')},depends=['prepare-metal','prepare-base'],desc='Room-temperature synthesis in open containers is described; no controlled gas, numeric pressure, stirring speed or separately timed post-addition hold. The printed 1.8 equivalents is retained, without replacing it by arithmetic from rounded quantities.')
 add(r,'precipitate','antisolvent_precipitation','Precipitate nanocrystals with ethyl acetate or heptane',['as-grown','ethyl-acetate','heptane'],'precipitated',SYN,stage='workup',retain=True,parents=['as-grown'],desc='Ethyl acetate and heptane are mutually exclusive alternatives, not co-added mandatory inputs. Source does not specify their volumes, solvent ratio or isolation hardware. Alternative inputs are listed for inventory completeness; the retained particle-state lineage does not assert both solvents were used.')
 add(r,'wash','ethyl_acetate_washing','Wash the precipitated nanocrystals with ethyl acetate',['precipitated','ethyl-acetate'],'washed',SYN,stage='workup',retain=True,desc='Wash count, volume and separation conditions are not reported; no centrifugation settings are invented.')
 add(r,'redisperse','colloid_redispersion','Redisperse in DMSO or ethanol',['washed','dmso','ethanol'],'colloid',SYN,stage='workup',parents=['washed'],desc='DMSO and ethanol are mutually exclusive alternate redispersion solvents. Final volume, concentration and storage conditions are unreported. Alternative inputs are listed for inventory completeness; the particle-state lineage does not assert both solvents were used.')
 r['condition_options']=[{'id':'precipitation-ethyl-acetate','label':'Precipitate with ethyl acetate; mutually exclusive with the heptane option.','parameters':{},'evidence':deepcopy(SYN)},{'id':'precipitation-heptane','label':'Precipitate with heptane; mutually exclusive with the ethyl-acetate option.','parameters':{},'evidence':deepcopy(SYN)},{'id':'redispersion-dmso','label':'Redisperse in DMSO; mutually exclusive with the ethanol option.','parameters':{},'evidence':deepcopy(SYN)},{'id':'redispersion-ethanol','label':'Redisperse in ethanol; mutually exclusive with the DMSO option.','parameters':{},'evidence':deepcopy(SYN)}]
 p=P(r,'route-product','General '+formula+' preparation framework',SYN,st='colloid',explicit=True);p['phase']=F('Wurtzite ZnO host',E(5,'Figure 5')+E(7,'Pure ZnO phase discussion'),note='Phase supported in characterized examples; no refined dopant occupancy or guarantee of identical batches.')
