 T(r,'scale','route-product','author_preparation_scale','The authors report rapid, reproducible gram-quantity preparation in open containers without special atmospheric precautions or temperature stabilization. No exact isolated mass/yield is provided for the typical recipe.',E(2,'Introduction')+E(13,'Conclusion'),status='author_derived')
 link(r,'topo-'+metal,'TOPO processing and surface-dopant removal');link(r,'microscopy','Microscopy and electron diffraction');link(r,'dopant-series','Nominal-doping series');records.append(r)

