 add(r,'repeat-cycle','repeat_redispersion_precipitation','Repeat toluene resuspension and ethanol precipitation once',['first-cycle-solid','toluene','ethanol'],'powder',TOPO,{'total_cycles':Q(2,'cycles',TOPO)},stage='workup',retain=True,desc='Two total toluene/ethanol cycles, not two additional cycles. Powder drying method is not specified.')
 add(r,'heat-topo','topo_thermal_treatment','Heat the resulting powder in technical-grade TOPO',['powder','topo-technical'],'topo-treated',TOPO,{'temperature':Q(180,'°C',TOPO),'duration':Q(u='min',e=TOPO,minimum=30),'topo_mass':Q(u='g',e=TOPO)},stage='workup',desc='At least 30 min is reported. Atmosphere, vessel, heating ramp, powder/TOPO ratio and exact duration for individual characterized samples are not supplied.')
 add(r,'cool','cooling','Cool the TOPO-treated nanocrystals below 80 °C',['topo-treated'],'cooled-topo',TOPO,{'target_temperature':Q(u='°C',e=TOPO,maximum=80,maximum_exclusive=True)},stage='workup')
 add(r,'precipitate','product_precipitation','Precipitate the cooled TOPO-treated particles',['cooled-topo'],'topo-precipitate',TOPO,stage='workup',retain=True,desc='The source names ethanol washing next but does not independently specify the precipitation agent or its amount in this sentence.')
