 add(r,'redisperse','nonpolar_redispersion','Redisperse with 1 mg additional TOPO in a nonpolar solvent',['cleaned-topo-powder','topo-technical','toluene'],'topo-colloid',TOPO,{'additional_topo_mass':Q(1,'mg',TOPO),'solvent_volume':Q(u='mL',e=TOPO)},stage='workup',desc='Toluene is the explicitly discussed example; other nonpolar solvents are not named. The 1 mg is additional redispersion TOPO, not the unknown heated-bath amount.')
